// 401 自愈（2026-09-05）：浏览器持有「有效 pocket cookie + 失效 dsh-auth-* cookie」
// 时，门禁放行、上游拒绝 → 裸 401 且无任何恢复路径（正常密码页被 pocket cookie 短路）。
// 对 HTML 导航请求重定向到强制握手参数，重新签发 dsh-auth；循环由既有 handshake
// tracker（60s 内 3 次上限）与「已带参数则不再重定向」双保险兜底。
if (proxyRes.statusCode === 401 && !res.headersSent
  && (req.method === 'GET' || req.method === 'HEAD')
  && isHtmlRequest(req)
  && String(req.headers.cookie ?? '').includes('dsh-auth-')
  && !String(req.url ?? '').includes('dsh-pocket-auth')) {
  const target = String(req.url || '/') + (String(req.url).includes('?') ? '&' : '?') + 'dsh-pocket-auth=1';
  log?.(`401 self-heal: stale dsh-auth cookie on ${String(req.url).slice(0, 80)} -> redirect ${target.slice(0, 90)}`);
  res.writeHead(302, { location: target, 'cache-control': 'no-store' });
  res.end();
  proxyRes.destroy();
  return;
}
res.writeHead(proxyRes.statusCode ?? 502, proxyRes.headers);
proxyRes.pipe(res);

